CREATE TABLE animals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, animal_tag VARCHAR(100) NOT NULL, acquisition_financial_transaction_id BIGINT UNSIGNED NULL, species ENUM('cattle','sheep','goat','poultry','pig','other') NOT NULL, breed VARCHAR(100) NULL, sex ENUM('male','female','unknown') NOT NULL DEFAULT 'unknown', birth_date DATE NULL, acquisition_date DATE NULL, acquisition_cost DECIMAL(15,2) NULL, status ENUM('active','sold','deceased','culled') NOT NULL DEFAULT 'active', notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_animals_tag (animal_tag), UNIQUE KEY uq_animals_acquisition_ft (acquisition_financial_transaction_id), KEY idx_animals_species_status (species,status), CONSTRAINT chk_animals_cost CHECK (acquisition_cost IS NULL OR acquisition_cost >= 0), CONSTRAINT chk_animals_dates CHECK (birth_date IS NULL OR acquisition_date IS NULL OR acquisition_date >= birth_date), CONSTRAINT fk_animals_acquisition_ft FOREIGN KEY (acquisition_financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
